<?php
declare(strict_types=1);requireRole('admin');require_once __DIR__.'/../../config/database.php';$activePage='audit-log';$user=filter_input(INPUT_GET,'user',FILTER_VALIDATE_INT);$module=trim((string)($_GET['module']??''));$date=(string)($_GET['date']??'');$where=[];$params=[];if($user){$where[]='a.user_id=:user';$params['user']=$user;}if($module!==''){$where[]='a.module=:module';$params['module']=$module;}if($date!==''&&DateTimeImmutable::createFromFormat('Y-m-d',$date)){$where[]='DATE(a.created_at)=:date';$params['date']=$date;}$sql='SELECT a.*,COALESCE(u.full_name,"System") user_name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.id DESC LIMIT 500';try{$db=database();$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$users=$db->query('SELECT id,full_name FROM users ORDER BY full_name')->fetchAll();$modules=$db->query('SELECT DISTINCT module FROM activity_logs ORDER BY module')->fetchAll(PDO::FETCH_COLUMN);}catch(PDOException $e){error_log($e->getMessage());$rows=$users=$modules=[];}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/admin-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Audit Log</h1></div></header><main class="dashboard-content admin-operation-page audit-page"><form class="audit-filters" method="get"><input type="hidden" name="page" value="audit-log"><select name="user"><option value="">All Users</option><?php foreach($users as $row):?><option value="<?=(int)$row['id']?>" <?=$user===$row['id']?'selected':''?>><?=htmlspecialchars($row['full_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><select name="module"><option value="">All Modules</option><?php foreach($modules as $value):?><option value="<?=htmlspecialchars($value,ENT_QUOTES,'UTF-8')?>" <?=$module===$value?'selected':''?>><?=htmlspecialchars($value,ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><input type="date" name="date" value="<?=htmlspecialchars($date,ENT_QUOTES,'UTF-8')?>"><button class="admin-primary-action">Filter</button><a class="outline-action" href="dashboard.php?page=audit-log">Clear</a></form><section class="admin-data-card"><div class="admin-data-table-wrap"><table class="admin-data-table audit-table"><thead><tr><th>Timestamp</th><th>User</th><th>Role</th><th>Module</th><th>Action</th><th>Record Ref</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="admin-empty-row">No audit log entries available.</td></tr><?php else:foreach($rows as $row):?><tr><td><?=date('d M Y H:i:s',strtotime($row['created_at']))?></td><td><strong><?=htmlspecialchars($row['user_name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=ucwords(str_replace('-',' ',$row['role']))?></td><td><?=htmlspecialchars($row['module'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['action'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['record_reference']?:'—',ENT_QUOTES,'UTF-8')?></td><td><?=ucfirst($row['status'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
